                        ygbpianwu: {
                            skillTrigger(triggerName, player, skill) {
                                var next = game.createEvent(triggerName, false);
                                next.player = player;
                                next.skill = skill;
                                next.setContent(() => {
                                    event.trigger(event.name);
                                });
                            },
                            init(player, skill) {
                                lib.skill[skill].skillTrigger('shijian_init', player, skill);
                            },
                            onremove(player, skill) {
                                lib.skill[skill].skillTrigger('shijian_removeSkill', player, skill);
                            },
                            audio: 'ext:阳光包/audio:4',
                            trigger: {
                                global: 'phaseBefore',
                                player: ['damageEnd', 'phaseJieshuBegin'],
                                source: 'damageSource',
                            },
                            forced: true,
                            charlotte: true,
                            fixed: true,
                            filter(event, player, name) {
                                if (name == 'phaseBefore' && game.phaseNumber != 0) return false;
                                if (name == 'damageSource' && game.roundNumber > 3) {
                                    return false;
                                }
                                if (
                                    game
                                        .filterPlayer()
                                        .map((p) => p.skills.filter((s) => /^ygb_shijian_createSkill_[0-9]+$/.test(s)).length)
                                        .flat(1)
                                        .reduce((p, n) => p + n, 0) >= 35
                                ) {
                                    return false;
                                }
                                return [player.name, player.name1, player.name2].includes('ygb_shijian') || (game.ygb_shijian && game.ygb_shijian.players.includes(player));
                            },
                            content() {
                                lib.skill[event.name].skillTrigger('shijian_addSkill', player, event.name);
                                var chat = ['获得技能是随机生成的,请仔细看看', '是欧皇技能还是非酋技能呢？', '听说<在线更新>这个扩展相当不错'].randomGet();
                                player.chat(chat);
                            },
                            ai: {
                                maixie: true,
                                maixie_hp: true,
                            },
                        },
