                        ygbchenju: {
                            trigger: {
                                player: ['enterGame', 'phaseZhunbeiBegin', 'phaseJieshuBegin', 'damageEnd'],
                                global: 'gameDrawAfter',
                            },
                            audio: 'ext:阳光包/audio:2',
                            forced: true,
                            content() {
                                'step 0';
                                var list;
                                var grouplist;
                                if (_status.characterlist) {
                                    list = [];
                                    grouplist = [];
                                    for (var i = 0; i < _status.characterlist.length; i++) {
                                        var name = _status.characterlist[i];
                                        list.push(name);
                                    }
                                } else if (_status.connectMode) {
                                    list = get.charactersOL(function (i) {
                                        return true;
                                    });
                                } else {
                                    list = get.gainableCharacters(function (info) {
                                        return true;
                                    });
                                }
                                var players = game.players.concat(game.dead);
                                for (var i = 0; i < players.length; i++) {
                                    list.remove(players[i].name);
                                    list.remove(players[i].name1);
                                    list.remove(players[i].name2);
                                }
                                list.remove(name);
                                player
                                    .chooseButton(true)
                                    .set('ai', function (button) {
                                        return Math.random();
                                    })
                                    .set('createDialog', ['请选择一张武将牌', [list.randomGets(5), 'character']]);
                                ('step 1');
                                var list = [];
                                var listm = [];
                                listm = lib.character[result.links[0]][3];
                                var func = function (skill) {
                                    var info = get.info(skill);
                                    //if(info.unique||info.charlotte||info.zhuSkill||info.dutySkill) return false;
                                    if (info.unique || info.charlotte || info.zhuSkill || info.hiddenSkill) return false;
                                    return true;
                                };
                                for (var i = 0; i < listm.length; i++) {
                                    if (func(listm[i])) list.add(listm[i]);
                                }
                                event.skills = list;
                                player.chooseControl(list).set('prompt', '请选择一个技能');
                                ('step 2');
                                var skill = result.control;
                                event.skill = skill;
                                player
                                    .chooseTarget('请选择要获得技能的角色', function (card, player, target) {
                                        return true;
                                    })
                                    .set('ai', function (target) {
                                        return get.attitude(player, target);
                                    });
                                ('step 3');
                                if (result.bool) {
                                    var target = result.targets[0];
                                    player.line(target);
                                    if (target.storage.ygbchenju) target.removeSkill(target.removeSkill(target.storage.ygbchenju));
                                    target.storage.ygbchenju = skill;
                                    target.addSkillLog(skill);
                                } else event.finish();
                            },
                        },
